import java.util.*;

class Solution {
    public String noTwins(String s) {
        int n = s.length();
        int[] cnt = new int[26];
        for (char c : s.toCharArray()) cnt[c - 'a']++;
        for (int c : cnt) if (c > (n + 1) / 2) return "";   // impossible
        StringBuilder sb = new StringBuilder();
        int prev = -1;
        for (int pos = 0; pos < n; pos++) {
            int m = n - pos - 1;                             // slots left after this one
            for (int ch = 0; ch < 26; ch++) {
                if (cnt[ch] == 0 || ch == prev) continue;
                cnt[ch]--;
                if (feasible(cnt, ch, m)) { sb.append((char) ('a' + ch)); prev = ch; break; }
                cnt[ch]++;                                   // undo and try next letter
            }
        }
        return sb.toString();
    }

    // can the remaining counts fill m slots when 'last' was just used?
    private boolean feasible(int[] cnt, int last, int m) {
        if (cnt[last] > m / 2) return false;
        for (int c : cnt) if (c > (m + 1) / 2) return false;
        return true;
    }
}

