class Solution:
    def noTwins(self, s: str) -> str:
        cnt = Counter(s)
        n = len(s)
        if max(cnt.values()) > (n + 1) // 2: return ""
        out, prev = [], ""
        for pos in range(n):
            m = n - pos - 1
            for ch in sorted(cnt):
                if cnt[ch] == 0 or ch == prev: continue
                cnt[ch] -= 1
                ok = cnt[ch] <= m // 2 and all(v <= (m + 1) // 2 for v in cnt.values())
                if ok:
                    out.append(ch); prev = ch; break
                cnt[ch] += 1
        return "".join(out)

