function noTwins(s) {
  const c = new Array(26).fill(0); for (const ch of s) c[ch.charCodeAt(0) - 97]++;
  const n = s.length; if (Math.max(...c) > Math.ceil(n / 2)) return "";
  let res = "", prev = -1;
  for (let left = n; left > 0; left--) {
    // if some letter is forced (count equals ceil(left/2) with left odd), it must go now
    let pick = -1;
    const mx = Math.max(...c);
    if (left % 2 === 1 && mx === (left + 1) / 2) pick = c.indexOf(mx);
    else {
      for (let i = 0; i < 26; i++) {
        if (!c[i] || i === prev) continue;
        c[i]--; const rem = left - 1; let ok = c[i] <= Math.floor(rem / 2);
        for (let j = 0; j < 26 && ok; j++) if (c[j] > Math.ceil(rem / 2)) ok = false;
        c[i]++; if (ok) { pick = i; break; }
      }
    }
    c[pick]--; prev = pick; res += String.fromCharCode(97 + pick);
  }
  return res;
}
